      de: ["Die Burg wurde 2006 in die UNESCO-Weltkulturerbeliste aufgenommen.", "Der Johanniterorden hielt die Burg von 1142 bis 1271.", "Die äußere Mauer ist durch 13 massive Rundtürme verstärkt.", "Die Festung konnte im Mittelalter eine Garnison von 2.000 Soldaten beherbergen.", "Sultan Baibars eroberte die Burg im April 1271.", "Die Burg liegt an der Südspitze des Dschebel-Ansarija-Gebirges."],
